341	int DiskAnnBuilder::prune_internal(IndexThreads::Pointer threads) {
342	  auto task_group = threads->make_group();
343	  if (!task_group) {
344	    LOG_ERROR("Failed to create task group");
345	    return IndexError_Runtime;
346	  }
347	
348	  std::atomic<uint64_t> finished{0};
349	  for (size_t i = 0; i < threads->count(); ++i) {
350	    task_group->submit(ailego::Closure ::New(this, &DiskAnnBuilder::do_prune, i,
351	                                             threads->count(), &finished));
352	  }
353	
354	  {
355	    std::unique_lock<std::mutex> lk(mutex_);
356	    while (finished.load() < entity_.doc_cnt()) {
357	      cond_.wait_until(lk, std::chrono::system_clock::now() +
358	                               std::chrono::seconds(check_interval_secs_));
359	      if (error_.load(std::memory_order_acquire)) {
360	        LOG_ERROR("Failed to prune index while waiting finish");
361	        return errcode_;
362	      }
363	      LOG_INFO("Prune cnt %zu, finished percent %.3f%%",
364	               (size_t)finished.load(),
365	               finished.load() * 100.0f / entity_.doc_cnt());
366	    }
367	  }
368	
369	  if (error_.load(std::memory_order_acquire)) {
370	    LOG_ERROR("Failed to prune index while waiting finish");
371	    return errcode_;
372	  }
373	  task_group->wait_finish();
374	
375	  return 0;
