429	int DiskAnnBuilder::generate_quantized_data(IndexThreads::Pointer threads) {
430	  LOG_INFO("Starting PQ Generate: Query Memory Limit: %lf, Chunk Num: %u",
431	           memory_limit_, pq_chunk_num_);
432	
433	  ailego::ElapsedTime timer;
434	
435	  if (!quantizer_) {
436	    LOG_ERROR("Quantizer not exist");
437	    return IndexError_NoReady;
438	  }
439	
440	  size_t num_vecs = holder_->count();
441	  auto &codes = entity_.block_compressed_data();
442	  codes.resize(num_vecs * pq_chunk_num_);
443	
444	  auto iter = holder_->create_iterator();
445	  if (!iter) {
446	    LOG_ERROR("Create iterator for holder failed");
447	    return IndexError_Runtime;
