273	        "No Chunk Num input. Quantizing %u dimension data into %u dimension.",
274	        build_meta_.dimension(), requested_chunk_num);
275	  }
276	
277	  pq_chunk_num_ = requested_chunk_num;
278	  if (memory_limit_set_) {
279	    size_t memory_limit_bytes =
280	        static_cast<size_t>(get_memory_in_bytes(memory_limit_));
281	    size_t budget_chunk_num = memory_limit_bytes / doc_cnt;
282	    if (budget_chunk_num == 0) {
283	      LOG_ERROR("Insufficient memory limit for vec, memory: %zu, vec num: %zu",
284	                memory_limit_bytes, doc_cnt);
285	      return IndexError_InvalidArgument;
286	    }
287	    pq_chunk_num_ = std::min(pq_chunk_num_,
288	                             static_cast<uint32_t>(std::min<size_t>(
289	                                 budget_chunk_num, build_meta_.dimension())));
290	  }
291	
292	  if (pq_chunk_num_ == 0 || pq_chunk_num_ > build_meta_.dimension()) {
293	    LOG_ERROR("PQ Chunk Num is more than dimension, chunk num: %u, dim: %u",
294	              pq_chunk_num_, build_meta_.dimension());
295	    return IndexError_InvalidArgument;
296	  }
297	
298	  LOG_INFO("Quantizing %u dimension data into %u bytes.",
299	           build_meta_.dimension(), pq_chunk_num_);
300	
301	  return 0;
302	}
